export const WORDS = entries.split('\n').map((line, index) => {
  const [id, ipa, pos, definitions, cue, example, ...contexts] = line.split('|');
  const [meaning, ...aliases] = definitions.split('；');
  return {
    id, ipa, pos, meaning, aliases, cue, example,
    contexts: contexts.map(sentence => sentence.replace('____ .', '____.').replace('____ :', '____:').replace('____ ,', '____,')),
    index: index + 1,
  };
});

export const WORD_BY_ID = Object.fromEntries(WORDS.map(word => [word.id, word]));
